(76, 'ESPALDAR NO SUBE.\r\nSE REALIZA REVISIÓN DEL EQUIPO, SE ENCUENTRAN GUAYAS DE ACTUADOR FOWLER MAL POSICIONADAS. SE REALIZA AJUSTE Y SE ENCUENTRA MOTOR FUNCIONAL.\r\nDURANTE REVISIÓN SE EVIDENCIA LA PRESENCIA DE LIQUIDOS/ACIDOS DENTRO DE MEMBRANAS DE BARANDA POR MALOS PROCESOS DE LIMPIEZA LO CUAL EMPIEZA A AFECTAR OTROS COMPONENTES DE LAS BARANDA Y EL CHASIS DE LA CAMA POR COMIENZOS DE OXIDACIÓN', NULL, 1, 2654, '', '2019-11-13', '16033'),
(77, 'NO HAY TESTIGOS ENCENDIDOS, COMO SI ESTUBIERA DESCONECTADA.\r\nSE REALIZA VERIFICACION DEL EQUIPO. PRUEBA DE TOMA CORRIENTE, CABLE AC Y SUMINISTRO A CONTROL BOX, SE EVIDENCIA QUE ESTE ULTIMO ESTA AVERIADO Y NECESITA CAMBIO.\r\nSE PRUEBAN CONTROLES DE BARANDA. NO HAY EVIDENCIA DE HUMEDAD.\r\nDAÑO PUEDE DEBERSE A FALLA ELECTRICA, EN LA ULTIMA REVISION DEL EQUIPO EL 18/10/2019. DONDE SE ECNONTRABA FUNCIONANDO', NULL, 1, 2625, '', '2019-10-24', '16011'),
(78, 'CONTROL DE BARANDA IZQUIERDO NO FUNCIONABA LA NOCHE ANTERIOR.\r\nSE REALIZA INSPECCION DEL EQUIPO, SE REVISAN MEMBRANAS, Y SE EVIDENCIA GRANDES SIGNOS DE SANGRE/FLUIDOS. SE PRUEBA CONTROL Y SE ENCUENTRA FUNCIONAL POR LE MOMENTO.\r\nFALLO SE DEBE A LA PRESENCIA DE HUMEDAD DENTRO DEL CONTROL POR MALOS PROCESOS DE LIMPIEZA Y DESINFECCION', NULL, 1, 2625, '982e095bd60b436db8c12450166b3e6f.pdf', '2019-10-18', '15296'),
(79, 'CAMA BLOQUEADA.\r\nSE REALIZA REVISION DEL EQUIPO. SE ENCUENTRA PANEL CON BARANDA IZQUIERDA AVERIADA, PRESENTA UN BOTON SIN FUNCIONAMIENTO Y BLOQUEA EL EQUIPO. NO HAY EVIDENCIA DE HUMEDAD NI LIQUIDOS.\r\nDURANTE REVISION SE ENCUENTRA MOTORHIGH/LOW DE LOS PIES CON SONIDO IRREGULAR (HM-17-304). SE RECOMIENDA CAMBIO. NO HAY DAÑO APARENTE Y SE DESCONOCE LA CAUSA DEL SONIDO', NULL, 1, 2616, 'f6c546d38360d846224acaeee505bd99.pdf', '2019-11-05', '16017'),
(80, 'SEGUN ORDEN DE TRABAJO 5587 \"EKG GRANDE NO IMPRIME\". SE REALIZA REVISION DEL EQUIPO CON SIMULADOR Y RESPONDE CORRECTAMENTE. EQUIPO OK', NULL, 1, 269, '60e91597972190c989350674a096597a.pdf', '2020-01-08', '16815'),
(81, 'SE ENCUENTRA SENSOR SPO2 DEFECTUOSO, SE INSTALA SENSOR NUEVO ENTREGADO POR EL CLIENTE. SE REALIZAN PRUEBAS CON BUENOS RESULTADOS', NULL, 1, 593, '7dc80b81c724e3ece3803682e8ecb5bb.pdf', '2020-01-08', '16816'),
(82, 'CONTROL DE BARANDA NO FUNCIONA. \r\nSE REALIZA INSPECCION DEL EQUIPOY SE VERIFICA CONTROL DE BARANDA. SE ENCEUNTRA EL CABLE DESCONECTADO Y SE PRUEBA. MOVIMEINTOS OK, LOS DEMAS CONTROLES OK.', NULL, 1, 1878, '2ee70c9889cda3e06d300c75ed490b3f.pdf', '2019-10-02', '15258'),
(83, 'BATERIA NO CARGA.\r\nSE REALIZA SEGUIMIENTO DE BATERIA DE EQUIPO, EL CUAL SE HABIA PRESENCIADO DURANTE PREVENTIVO QUE NO CARGABA. DURANTE TIEMPO DE SEGUIMIENTO BATERIA NO CARGO Y SE ENCEUNTRA COMPLETAMENTE DESCARGADA. SE DEBERIA CAMBIAR POR DAÑO.\r\n\r\nEQUIPO FUNCIONAL CONECTADO A TOMA CORRIENTE', NULL, 1, 1785, '92e5b7acf57ce1557bd2de7438d2f0aa.pdf', '2019-10-02', '15257'),
(84, 'SEGÚN ORDEN DE TRABAJO 5654 \"VENTILADOR NO ENTREGA LOS VOLÚMENES ASIGNADOS Y PRESENTA FUGA\"', NULL, 1, 1913, '424c3bacaeb069f05dcf6e97a4c1f788.pdf', '2020-01-07', '5654'),
(85, 'SEGÚN ORDEN DE TRABAJO 5663 \"MAQUINA PRESENTA FUGA NO DETECTABLE\"', NULL, 1, 466, '28035ecfefc81b7545d219732b6a0f14.pdf', '2020-01-10', '5663'),
(86, 'BARANDA NO AJUSTA Y SE BAJA SOLA.\r\n\r\nSE REALIZA DESMONTE DE BARANDA SUPERIOR IZQUIERDA, SE LIMPIAN PIEZAS Y SE AJUSTA RESORTE DEL PASADOR DE LIBERACION. SE COMPRUEBA CORRECTO FUNCIONAMIENTO Y SONIDO CLICK DEL SEGURO.\r\n\r\nSE INSPECCIONA LA CAMA Y SUS MOVIMIENTOS. SE EVIDENCIA SONIDO IRREGULAR EN EL MOTOR HIGH/LOW DE LOS PIES. SE RECOMIENDA CAMBIO.\r\nA ESPERA DE CONFIRMACIÓN DE GARANTIA POR EL DISTRIBUIDOR. SE DESCONOCE CAUSA DEL SONIDO.', NULL, 1, 2626, 'f694afc331625b4b9e8b3e05519f6a8c.pdf', '2019-09-05', '14379'),
(87, 'MOTOR HIGH/LOW PIES CON RUIDO.\r\nSE REALIZA VERIFICACION DEL EQUIPO. SE REALIZA CAMBIO DE MOTOR HIGH/LOW DE LOS PIES EL CUAL PRESENTA RUIDO IRREGULAR AL MOMENTO DE ELEVAR LA CAMA. SE REALIZAN PRUEBAS DE FUNCIONAMIENTO, EQUIPO FUNCIONAL SIN NOVEDAD', NULL, 1, 2626, 'd9d201adcf54b92a82271938b7031cd4.pdf', '2019-10-18', '15295'),
(88, 'CONTROL BOX AVERIADO, CABECERA NO SUBIA COMPLETO.\r\n\r\nSE REALIZA CAMBIO DE CONTROL BOX EL CUAL SE ENCONTRABA AVERADO.\r\nSER COMPRUEBAN MOVIMEITNOS Y CONTROLES DE BARANDA.\r\nEQUIPO EN CORRECTO ESTADO FUNCIONAL.\r\nSE DEJA CARGANDO.\r\n', NULL, 1, 2633, '7d46465681f64dc7e73cb38aeb5d75b3.pdf', '2019-09-05', '14378'),
(89, 'CABEZOTE NO SUBE.\r\nSE PRUEBA SUMINISTRO DE ENERGIA DEL EQUIPO, TESTIGOS NO ENCIENDEN, CABLE AC EN BUEN ESTADO FISICO Y FUNCIONAL.\r\nCAMA BLOQUEADA Y DESCARGADA.\r\nCONTROL BOX AVERIADO. SE DEBE CAMBIAR.\r\nNOTA. SE DEBERIA PROBAR MOTRO DEL CABEZAL UNA VEZ SE CAMBIE EL CONTROL BOX. DE MOMENTO NO SE PUEDEN EJECUTAR MAS PRUEBAS', NULL, 1, 2633, '2a5452039572fab56cda76a9f81773c4.pdf', '2019-09-02', '14374'),
(90, 'CAMA BLOQUEADA.\r\nSE REALIZA CAMBIO DE CONTROL BOX AVERIADO.\r\nSE COMPRUEBAN MOVIEMIENTOS Y SE DEJA EQUIPO CARGANDO.\r\nSE VERIFICAN BARANDAS Y CONTROL IZQUIERDO PRESENTA MUCHA HUMEDAD Y REMANENTES DE SANGRE. SE LIMPIA Y SE LE DA LA RECOMENDACIÓN DE CUIDADO', NULL, 1, 2632, '9e2c6f0c05149c36389530bffde3e88f.pdf', '2019-08-16', '14339'),
(91, 'LA CAMA NO FUNCIONA CORRECTAMENTE.\r\nSE REALIZA VISITA PARA PRESTAR EL SERVICIO. SIN EMBARGO NO SE PUEDE RALIZAR POR PACIENTE AISLADO', NULL, 1, 2650, '7e319d0ca05abe0834a38434151a18f5.pdf', '2019-06-19', '0853'),
(92, 'BARANDA DE PIECERO NO BAJA/ SE QUEDA RIGIDA.\r\nSE REALIZA VERIFICACIÓN DEL EQUIPO, SE DESTAPA COMPONENTE Y SE COMPRUEBA RESORTE DE BARANDA MAL UBICADO, SE REALIZA AJUSTE Y SE DEJA EQUIPO FUNCIONAL.\r\nSE RECOMIENDA CONECTAR EL EQUIPO EN TOMA REGULADO', NULL, 1, 2650, '313e53e323bc71e66b3eafedb2006d20.pdf', '2019-07-31', '0423'),
(93, 'RUIDO EN MOTOR HIGH/LOW DE PIES.\r\nSE REALIZA CAMBIO/INSTALACION DE MOTOR HIGH/LOW DE LOS PIES EL CUAL SE REPORTO POR DAÑO.\r\n\r\nSE REALIZA VERIFICACIÓN DE MOVIMIENTOS Y SE ENCUENTRA EQUIPO COMPLETAMENTE FUNCIONAL.\r\n\r\nSE EVIDENCIA RASTROS DE FLUIDOS EN EL EQUIPO, EVIDENCIA DE INADECUADOS PROCESOS DE LIMPIEZA Y DESINFECCION.\r\n\r\nPENDIENTE SUBSANAR RUIDO DE QUINTA RUEDA, ESPERA DE REPUESTOS.', NULL, 1, 2645, 'edef49ca48dd7735989ebac2ba3323d8.pdf', '2019-09-19', '16204'),
(94, 'RUIDO DURANTE TRANSPORTE.\r\nSE REALIZA DESMONTE DE QUINTA RUEDA, SE INSTALA LA DE OTRO EQUIPO Y SE PRUEBA.\r\n5TA RUEDA APARENTEMENTE DAÑADA, SE INSTALA EN EL DE PRUEBA Y SE COMPRUEBA O EVIDENCIA EL MISMO RUIDO. SE REALIZAN PRUEBAS CON Y SIN 5TA RUEDA, SE SUGIERE EL CAMBIO, SE DESCONOCE EL RUIDO O DAÑO, NO HAY EVIDENCIA DE COMPONENTES ROTOS O DAÑADOS.\r\nSE INSPECCIONA EQUIPO Y SE ENCUENTRA ADICIONALMENTE RUIDO EN MOTRO HIGH/LOW DE LOS PIES DURANTE ELEVACION DE CAMA, SE DESCONOCE CAUSA Y SE SUGIERE CAMBIO', NULL, 1, 2645, '', '2019-09-06', '14383'),
(95, 'RUIDO DURANTE TRANSPORTE.\r\nSE REALIZA VERIFICACION DE EQUIPO NO ENCONTRANDOSE FALLA O RUIDO REPORTADO.\r\nSE DEJA EN SEGUIMIENTO SI VUELVE A PRESENTAR RUIDO\r\n', NULL, 1, 2645, 'b0068521fc3883f75b47e918b652bf7f.pdf', '2019-07-31', '0422'),
(96, 'INSTALACION 5TA RUEDA.\r\nSE REALIZA INSTALCION DE QUINTA RUEDA LA CUAL PRESENTA RUIDO DURANTE TRANSPORTE.\r\nSE REALIZA PRUEBA Y TRANSPORTE DEL EQUIPO NO NOTICIANDO MAS RUIDO O NOVEDADES.\r\nEQUIPO SE  ENCEUNTRA OPERATIVO', NULL, 1, 2645, '8da625d34ea75652483ea7467e2509e0.pdf', '2020-01-13', '18102'),
